/* ===== LearnForge Design System ===== */

:root {
  --color-primary: #0A0A0A;
  --color-accent: #E6FF32;
  --color-accent-hover: #CCED20;
  --color-accent-subtle: rgba(230, 255, 50, 0.12);
  --color-burgundy: #7F2A23;
  --color-burgundy-light: #9E3A31;
  --color-bg: #FFFFFF;
  --color-surface: #F7F7F8;
  --color-surface-alt: #EEEEF0;
  --color-border: #E5E5E7;
  --color-border-light: #F0F0F2;
  --color-text-primary: #0A0A0A;
  --color-text-secondary: #52525B;
  --color-text-muted: #A1A1AA;
  --color-white: #FFFFFF;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;
  --text-7xl: 4.5rem;

  --spacing-1: 0.25rem;
  --spacing-2: 0.5rem;
  --spacing-3: 0.75rem;
  --spacing-4: 1rem;
  --spacing-5: 1.25rem;
  --spacing-6: 1.5rem;
  --spacing-8: 2rem;
  --spacing-10: 2.5rem;
  --spacing-12: 3rem;
  --spacing-16: 4rem;
  --spacing-20: 5rem;
  --spacing-24: 6rem;
  --spacing-32: 8rem;

  --radius-sm: 0.375rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.25rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  --shadow-xs: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.08), 0 2px 4px -2px rgba(0,0,0,0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.06);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.05);
  --shadow-card: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-card-hover: 0 12px 24px rgba(0,0,0,0.1);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease-out;

  --container-max: 1200px;
  --nav-height: 72px;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text-primary);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
ul, ol { list-style: none; }
input, textarea, select { font: inherit; color: inherit; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.15; font-weight: 700; color: var(--color-text-primary); }
h1 { font-size: var(--text-5xl); letter-spacing: -0.03em; }
h2 { font-size: var(--text-4xl); letter-spacing: -0.02em; }
h3 { font-size: var(--text-2xl); letter-spacing: -0.01em; font-weight: 600; }
h4 { font-size: var(--text-xl); font-weight: 600; }

@media (max-width: 768px) {
  h1 { font-size: var(--text-3xl); }
  h2 { font-size: var(--text-2xl); }
  h3 { font-size: var(--text-xl); }
}

/* ===== Container ===== */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--spacing-6);
}

/* ===== Navigation ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-light);
  height: var(--nav-height);
  transition: box-shadow var(--transition-base);
}
.nav.scrolled { box-shadow: var(--shadow-md); }
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--spacing-6);
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  font-weight: 800;
  letter-spacing: -0.03em;
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}
.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-primary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  font-size: var(--text-lg);
  font-weight: 900;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: var(--spacing-1);
}
.nav-links a {
  font-size: var(--text-sm);
  font-weight: 500;
  padding: var(--spacing-2) var(--spacing-3);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
  color: var(--color-text-secondary);
  white-space: nowrap;
}
.nav-links a:hover { color: var(--color-text-primary); background: var(--color-surface); }
.nav-cta {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
}
.nav-hamburger {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}
.nav-hamburger:hover { background: var(--color-surface); }
.nav-hamburger span {
  display: block;
  width: 20px;
  height: 2px;
  background: var(--color-text-primary);
  transition: var(--transition-base);
  position: relative;
}
.nav-hamburger span::before,
.nav-hamburger span::after {
  content: '';
  position: absolute;
  width: 20px;
  height: 2px;
  background: var(--color-text-primary);
  transition: var(--transition-base);
}
.nav-hamburger span::before { top: -6px; }
.nav-hamburger span::after { top: 6px; }
.nav-hamburger.active span { background: transparent; }
.nav-hamburger.active span::before { top: 0; transform: rotate(45deg); }
.nav-hamburger.active span::after { top: 0; transform: rotate(-45deg); }

.mobile-menu {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  padding: var(--spacing-6);
  z-index: 999;
  flex-direction: column;
  gap: var(--spacing-2);
  animation: fadeIn 200ms ease-out;
}
.mobile-menu.active { display: flex; }
.mobile-menu a {
  font-size: var(--text-lg);
  font-weight: 500;
  padding: var(--spacing-3) var(--spacing-4);
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.mobile-menu a:hover { color: var(--color-text-primary); background: var(--color-surface); }
.mobile-menu .btn-primary { text-align: center; margin-top: var(--spacing-4); }

@media (max-width: 900px) {
  .nav-links, .nav-cta .btn-secondary { display: none; }
  .nav-hamburger { display: flex; }
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2);
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  font-weight: 600;
  padding: 0.7rem 1.5rem;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
  text-align: center;
}
.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(230,255,50,0.3);
}
.btn-primary:active { transform: translateY(0); }
.btn-secondary {
  background: transparent;
  color: var(--color-text-primary);
  border: 1.5px solid var(--color-border);
}
.btn-secondary:hover {
  border-color: var(--color-text-primary);
  background: var(--color-surface);
}
.btn-dark {
  background: var(--color-primary);
  color: var(--color-accent);
}
.btn-dark:hover {
  background: #1a1a1a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}
.btn-lg { padding: 0.9rem 2rem; font-size: var(--text-base); }
.btn-sm { padding: 0.5rem 1rem; font-size: var(--text-xs); }

/* ===== Section ===== */
.section {
  padding: var(--spacing-20) 0;
}
.section-sm { padding: var(--spacing-12) 0; }
.section-lg { padding: var(--spacing-24) 0; }
.section-dark {
  background: var(--color-primary);
  color: var(--color-white);
}
.section-dark h2, .section-dark h3, .section-dark h4 { color: var(--color-white); }
.section-dark p { color: rgba(255,255,255,0.7); }
.section-surface { background: var(--color-surface); }
.section-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto var(--spacing-12);
}
.section-header p {
  margin-top: var(--spacing-4);
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
}
.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-burgundy);
  background: rgba(127,42,35,0.08);
  padding: var(--spacing-1) var(--spacing-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--spacing-4);
}

/* ===== Hero ===== */
.hero {
  padding: var(--spacing-16) 0 var(--spacing-12);
  background: linear-gradient(180deg, var(--color-surface) 0%, var(--color-bg) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  z-index: 1;
}
.hero h1 {
  max-width: 800px;
  margin-bottom: var(--spacing-6);
}
.hero-subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  max-width: 620px;
  margin-bottom: var(--spacing-8);
  line-height: 1.7;
}
.hero-actions {
  display: flex;
  gap: var(--spacing-4);
  margin-bottom: var(--spacing-10);
  flex-wrap: wrap;
  justify-content: center;
}

/* Hero Tabs */
.hero-tabs {
  display: flex;
  gap: var(--spacing-1);
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--spacing-6);
}
.hero-tab {
  padding: var(--spacing-2) var(--spacing-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
}
.hero-tab.active {
  background: var(--color-primary);
  color: var(--color-accent);
}
.hero-tab:hover:not(.active) { color: var(--color-text-primary); }

/* Hero Preview */
.hero-preview {
  width: 100%;
  max-width: 960px;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--color-border);
  background: var(--color-white);
}
.hero-preview-frame {
  display: none;
  padding: var(--spacing-8);
  min-height: 360px;
  animation: fadeIn 300ms ease-out;
}
.hero-preview-frame.active { display: block; }
.hero-preview-bar {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
  padding: var(--spacing-3) var(--spacing-4);
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}
.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.hero-preview-dot:nth-child(1) { background: #FF5F56; }
.hero-preview-dot:nth-child(2) { background: #FFBD2E; }
.hero-preview-dot:nth-child(3) { background: #27C93F; }

/* Mock dashboard UI inside preview */
.mock-dashboard {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: var(--spacing-4);
  min-height: 280px;
}
.mock-sidebar {
  background: var(--color-primary);
  border-radius: var(--radius-lg);
  padding: var(--spacing-4);
  color: rgba(255,255,255,0.6);
  font-size: var(--text-xs);
}
.mock-sidebar-item {
  padding: var(--spacing-2) var(--spacing-3);
  border-radius: var(--radius-sm);
  margin-bottom: var(--spacing-1);
}
.mock-sidebar-item.active {
  background: rgba(230,255,50,0.15);
  color: var(--color-accent);
}
.mock-main {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
}
.mock-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-3);
}
.mock-stat-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  padding: var(--spacing-4);
}
.mock-stat-value {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  font-weight: 700;
  color: var(--color-primary);
}
.mock-stat-label {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  margin-top: var(--spacing-1);
}
.mock-chart {
  flex: 1;
  background: var(--color-surface);
  border-radius: var(--radius-md);
  padding: var(--spacing-4);
  display: flex;
  align-items: flex-end;
  gap: var(--spacing-2);
}
.mock-chart-bar {
  flex: 1;
  background: var(--color-accent);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  min-height: 20px;
  opacity: 0.7;
}
.mock-chart-bar:nth-child(even) { background: var(--color-burgundy); opacity: 0.5; }

/* Student view mock */
.mock-student {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
}
.mock-student-header {
  display: flex;
  align-items: center;
  gap: var(--spacing-4);
  padding-bottom: var(--spacing-4);
  border-bottom: 1px solid var(--color-border);
}
.mock-avatar {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--color-primary);
}
.mock-progress-bar {
  height: 8px;
  background: var(--color-surface-alt);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.mock-progress-fill {
  height: 100%;
  background: var(--color-accent);
  border-radius: var(--radius-full);
  width: 68%;
}
.mock-course-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-3);
}
.mock-course-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
  padding: var(--spacing-3);
  background: var(--color-surface);
  border-radius: var(--radius-md);
}
.mock-course-thumb {
  width: 60px;
  height: 40px;
  background: var(--color-primary);
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}
.mock-course-info { flex: 1; }
.mock-course-title {
  font-weight: 600;
  font-size: var(--text-sm);
  margin-bottom: 2px;
}
.mock-course-meta { font-size: var(--text-xs); color: var(--color-text-muted); }

@media (max-width: 768px) {
  .hero { padding: var(--spacing-10) 0 var(--spacing-8); }
  .mock-dashboard { grid-template-columns: 1fr; }
  .mock-sidebar { display: none; }
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-primary);
  padding: var(--spacing-10) 0;
}
.stats-bar-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-8);
  text-align: center;
}
.stat-item {}
.stat-value {
  font-family: var(--font-heading);
  font-size: var(--text-4xl);
  font-weight: 800;
  color: var(--color-accent);
  letter-spacing: -0.03em;
}
.stat-label {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.6);
  margin-top: var(--spacing-1);
  font-weight: 500;
}
@media (max-width: 640px) {
  .stats-bar-inner { grid-template-columns: 1fr; gap: var(--spacing-6); }
  .stat-value { font-size: var(--text-3xl); }
}

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--spacing-6);
}
.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-base);
}
.product-card:hover {
  box-shadow: var(--shadow-card-hover);
  transform: translateY(-4px);
  border-color: transparent;
}
.product-card:hover::before { transform: scaleX(1); }
.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-xl);
  margin-bottom: var(--spacing-5);
  background: var(--color-accent-subtle);
}
.product-card h3 {
  font-size: var(--text-xl);
  margin-bottom: var(--spacing-3);
}
.product-card p {
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  line-height: 1.7;
}
.product-card-link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-2);
  margin-top: var(--spacing-5);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-burgundy);
  transition: gap var(--transition-fast);
}
.product-card:hover .product-card-link { gap: var(--spacing-3); }
@media (max-width: 900px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 540px) {
  .products-grid { grid-template-columns: 1fr; }
}

/* ===== Feature Tabs (Why Choose Us) ===== */
.feature-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-2);
  justify-content: center;
  margin-bottom: var(--spacing-10);
}
.feature-tab {
  padding: var(--spacing-3) var(--spacing-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  border: 1.5px solid var(--color-border);
  transition: all var(--transition-fast);
}
.feature-tab:hover { border-color: var(--color-text-primary); color: var(--color-text-primary); }
.feature-tab.active {
  background: var(--color-primary);
  color: var(--color-accent);
  border-color: var(--color-primary);
}
.feature-panel {
  display: none;
  animation: fadeIn 300ms ease-out;
}
.feature-panel.active { display: block; }
.feature-panel-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-5);
}
.feature-item {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-4);
  padding: var(--spacing-5);
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  transition: background var(--transition-fast);
}
.feature-item:hover { background: var(--color-accent-subtle); }
.feature-item-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-lg);
}
.feature-item h4 { margin-bottom: var(--spacing-1); font-size: var(--text-base); }
.feature-item p { font-size: var(--text-sm); color: var(--color-text-secondary); }

/* ===== Global Scale ===== */
.global-scale-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-8);
  align-items: center;
}
.global-scale-map {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  font-size: 8rem;
  line-height: 1;
}
.global-scale-content h3 { margin-bottom: var(--spacing-4); }
.global-scale-content p { color: var(--color-text-secondary); margin-bottom: var(--spacing-6); }
.global-scale-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
}
.global-scale-list-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
  font-weight: 500;
}
.global-scale-check {
  width: 24px;
  height: 24px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-xs);
  color: var(--color-primary);
  flex-shrink: 0;
}
@media (max-width: 768px) {
  .global-scale-visual { grid-template-columns: 1fr; }
  .global-scale-map { min-height: 200px; font-size: 5rem; }
}

/* ===== AI Section ===== */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
}
.ai-card {
  background: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: transform var(--transition-base);
}
.ai-card:hover { transform: translateY(-4px); }
.ai-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  background: rgba(230,255,50,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-xl);
  margin-bottom: var(--spacing-5);
}
.ai-card h3 {
  color: var(--color-white);
  margin-bottom: var(--spacing-3);
}
.ai-card p { color: rgba(255,255,255,0.65); font-size: var(--text-sm); }
.ai-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-2);
  margin-top: var(--spacing-5);
}
.ai-tag {
  font-size: var(--text-xs);
  padding: 3px 10px;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.7);
}
@media (max-width: 768px) {
  .ai-grid { grid-template-columns: 1fr; }
}

/* ===== Testimonials Carousel ===== */
.testimonials-carousel {
  position: relative;
  overflow: hidden;
}
.testimonials-track {
  display: flex;
  transition: transform 500ms ease;
}
.testimonial-card {
  flex: 0 0 calc(33.333% - var(--spacing-4));
  margin: 0 var(--spacing-2);
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: box-shadow var(--transition-base);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-quote {
  font-size: var(--text-base);
  line-height: 1.7;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-6);
  position: relative;
  padding-left: var(--spacing-6);
}
.testimonial-quote::before {
  content: '"';
  position: absolute;
  left: 0;
  top: -4px;
  font-size: 2rem;
  color: var(--color-accent);
  font-family: Georgia, serif;
  line-height: 1;
}
.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
}
.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-accent-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: var(--text-sm);
  color: var(--color-burgundy);
}
.testimonial-name { font-weight: 600; font-size: var(--text-sm); }
.testimonial-role { font-size: var(--text-xs); color: var(--color-text-muted); }
.testimonial-badge {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 700;
  color: var(--color-burgundy);
  background: rgba(127,42,35,0.08);
  padding: 2px 8px;
  border-radius: var(--radius-full);
  margin-bottom: var(--spacing-3);
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-4);
  margin-top: var(--spacing-8);
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
}
.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-surface);
}
.carousel-dots {
  display: flex;
  gap: var(--spacing-2);
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-fast);
  cursor: pointer;
}
.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: var(--radius-full);
}
@media (max-width: 900px) {
  .testimonial-card { flex: 0 0 calc(50% - var(--spacing-4)); }
}
@media (max-width: 540px) {
  .testimonial-card { flex: 0 0 calc(100% - var(--spacing-4)); }
}

/* ===== Pricing Overview ===== */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--spacing-5);
}
.pricing-card {
  background: var(--color-white);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: all var(--transition-base);
  position: relative;
}
.pricing-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}
.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 1px var(--color-accent), var(--shadow-lg);
}
.pricing-card.featured::after {
  content: 'Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: var(--text-xs);
  font-weight: 700;
  padding: 2px 12px;
  border-radius: var(--radius-full);
}
.pricing-plan {
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-2);
}
.pricing-price {
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
  font-weight: 800;
  margin-bottom: var(--spacing-1);
}
.pricing-price span { font-size: var(--text-sm); font-weight: 500; color: var(--color-text-muted); }
.pricing-desc {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-6);
  padding-bottom: var(--spacing-6);
  border-bottom: 1px solid var(--color-border);
}
.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-3);
  margin-bottom: var(--spacing-8);
}
.pricing-feature {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-2);
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
}
.pricing-check {
  color: var(--color-burgundy);
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 2px;
}
.pricing-note {
  text-align: center;
  margin-top: var(--spacing-8);
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}
.pricing-note a { color: var(--color-burgundy); font-weight: 600; }
@media (max-width: 900px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 540px) {
  .pricing-grid { grid-template-columns: 1fr; }
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--spacing-4);
}
.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-3);
  padding: var(--spacing-6) var(--spacing-4);
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);
}
.integration-item:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.integration-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--color-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  font-weight: 800;
  color: var(--color-text-secondary);
}
.integration-name {
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--color-text-secondary);
  text-align: center;
}
@media (max-width: 900px) {
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
}
@media (max-width: 540px) {
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-3);
}
.faq-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition-fast);
}
.faq-item:hover { box-shadow: var(--shadow-sm); }
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-5) var(--spacing-6);
  font-size: var(--text-base);
  font-weight: 600;
  text-align: left;
  color: var(--color-text-primary);
  transition: background var(--transition-fast);
}
.faq-question:hover { background: var(--color-surface); }
.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1.5px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  transition: all var(--transition-base);
  flex-shrink: 0;
}
.faq-item.active .faq-icon {
  background: var(--color-accent);
  border-color: var(--color-accent);
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}
.faq-answer-inner {
  padding: 0 var(--spacing-6) var(--spacing-5);
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  line-height: 1.7;
}

/* ===== Social Proof ===== */
.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-10);
  flex-wrap: wrap;
  opacity: 0.5;
}
.social-proof-logo {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  font-weight: 800;
  color: var(--color-text-muted);
  letter-spacing: -0.02em;
}

/* ===== CTA Banner ===== */
.cta-banner {
  background: var(--color-primary);
  border-radius: var(--radius-2xl);
  padding: var(--spacing-16);
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(230,255,50,0.1) 0%, transparent 70%);
  pointer-events: none;
}
.cta-banner h2 { color: var(--color-white); margin-bottom: var(--spacing-4); position: relative; }
.cta-banner p { color: rgba(255,255,255,0.65); max-width: 500px; margin: 0 auto var(--spacing-8); position: relative; }
.cta-banner .btn { position: relative; }

/* ===== Footer ===== */
.footer {
  background: var(--color-primary);
  color: rgba(255,255,255,0.6);
  padding: var(--spacing-16) 0 var(--spacing-8);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--spacing-8);
  margin-bottom: var(--spacing-12);
}
.footer-brand p { font-size: var(--text-sm); line-height: 1.7; margin-top: var(--spacing-4); max-width: 280px; }
.footer-logo {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  font-weight: 800;
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}
.footer-logo-icon {
  width: 28px;
  height: 28px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
  font-weight: 900;
  font-size: var(--text-sm);
}
.footer-col h4 {
  color: var(--color-white);
  font-size: var(--text-sm);
  font-weight: 700;
  margin-bottom: var(--spacing-4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.footer-col a {
  display: block;
  font-size: var(--text-sm);
  padding: var(--spacing-1) 0;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--color-accent); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: var(--spacing-6);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--text-xs);
}
@media (max-width: 900px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: span 2; }
}
@media (max-width: 540px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
  .footer-bottom { flex-direction: column; gap: var(--spacing-3); text-align: center; }
}

/* ===== Feature Cards (generic 3-col) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
}
.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: all var(--transition-base);
}
.feature-card:hover {
  box-shadow: var(--shadow-card-hover);
  transform: translateY(-4px);
}
.feature-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-2xl);
  margin-bottom: var(--spacing-5);
}
.feature-card-icon.accent { background: var(--color-accent-subtle); }
.feature-card-icon.burgundy { background: rgba(127,42,35,0.08); }
.feature-card-icon.dark { background: rgba(10,10,10,0.06); }
.feature-card h3 { margin-bottom: var(--spacing-3); }
.feature-card p { color: var(--color-text-secondary); font-size: var(--text-sm); line-height: 1.7; }
@media (max-width: 768px) {
  .features-grid { grid-template-columns: 1fr; }
}

/* ===== Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
  position: relative;
}
.steps-grid::before {
  content: '';
  position: absolute;
  top: 40px;
  left: calc(16.666% + 24px);
  right: calc(16.666% + 24px);
  height: 2px;
  background: var(--color-border);
}
.step-card {
  text-align: center;
  position: relative;
  z-index: 1;
}
.step-number {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-primary);
  color: var(--color-accent);
  font-family: var(--font-heading);
  font-size: var(--text-lg);
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--spacing-5);
}
.step-card h3 { margin-bottom: var(--spacing-3); }
.step-card p { color: var(--color-text-secondary); font-size: var(--text-sm); }
@media (max-width: 768px) {
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
}

/* ===== Spotlight Cards ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
}
.spotlight-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: all var(--transition-base);
}
.spotlight-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-lg);
}
.spotlight-card h4 { margin-bottom: var(--spacing-2); }
.spotlight-card p { color: var(--color-text-secondary); font-size: var(--text-sm); }
@media (max-width: 768px) {
  .spotlight-grid { grid-template-columns: 1fr; }
}

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
}
.resource-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--spacing-8);
  transition: all var(--transition-base);
}
.resource-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.resource-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--color-accent-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-lg);
  margin-bottom: var(--spacing-4);
}
.resource-card h4 { margin-bottom: var(--spacing-2); }
.resource-card p { color: var(--color-text-secondary); font-size: var(--text-sm); margin-bottom: var(--spacing-4); }
.resource-link {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-burgundy);
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-2);
}
@media (max-width: 768px) {
  .resources-grid { grid-template-columns: 1fr; }
}

/* ===== File Types Grid ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--spacing-4);
}
.file-type-item {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--spacing-5);
  text-align: center;
  font-size: var(--text-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}
.file-type-item:hover {
  background: var(--color-accent-subtle);
  transform: translateY(-2px);
}

/* ===== Tools Grid ===== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-3);
}
.tool-category {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--spacing-5);
}
.tool-category-title {
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  font-weight: 700;
  margin-bottom: var(--spacing-3);
  color: var(--color-burgundy);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.tool-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-2);
}
.tool-item {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}
.tool-item::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  flex-shrink: 0;
}
@media (max-width: 900px) {
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 540px) {
  .tools-grid { grid-template-columns: 1fr; }
}

/* ===== Membership Pricing ===== */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
  margin-bottom: var(--spacing-12);
}
.membership-stat {
  text-align: center;
  padding: var(--spacing-8);
  background: var(--color-surface);
  border-radius: var(--radius-xl);
}
.membership-stat-value {
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
  font-weight: 800;
  color: var(--color-burgundy);
  margin-bottom: var(--spacing-2);
}
.membership-stat-desc {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
}
@media (max-width: 768px) {
  .membership-stats { grid-template-columns: 1fr; }
}

/* ===== Product Demo Accordion ===== */
.demo-accordion {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
}
.demo-accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-6) var(--spacing-8);
  font-size: var(--text-lg);
  font-weight: 600;
  background: var(--color-surface);
  transition: background var(--transition-fast);
}
.demo-accordion-trigger:hover { background: var(--color-surface-alt); }
.demo-accordion-icon {
  font-size: var(--text-xl);
  transition: transform var(--transition-base);
}
.demo-accordion.active .demo-accordion-icon { transform: rotate(180deg); }
.demo-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 400ms ease;
}
.demo-accordion-content-inner {
  padding: var(--spacing-8);
}

/* ===== Value Proposition ===== */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-6);
}
.value-card {
  text-align: center;
  padding: var(--spacing-8);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.value-card:hover {
  box-shadow: var(--shadow-lg);
